import { useRef, useState } from 'react';
import { IconAlertTriangle, IconCalendar } from '@tabler/icons-react';
import { CloseButton, Combobox, Group, Text, TextInput, useCombobox } from '@mantine/core';
import { formatDueDate, formatRelative, parseNaturalDate } from './parseNaturalDate';
import { getSuggestions } from './suggestions';
import classes from './NaturalDateInput.module.css';

export interface NaturalDateInputProps {
  label: string;
  value: Date | null;
  onChange: (value: Date | null) => void;
  placeholder?: string;
}

function sameDate(a: Date | null, b: Date | null) {
  return (a?.getTime() ?? null) === (b?.getTime() ?? null);
}

const PROPER_NAMES = new Set([
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
  'sunday',
  'mon',
  'tue',
  'tues',
  'wed',
  'thu',
  'thur',
  'thurs',
  'fri',
  'sat',
  'sun',
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
  'jan',
  'feb',
  'mar',
  'apr',
  'jun',
  'jul',
  'aug',
  'sep',
  'sept',
  'oct',
  'nov',
  'dec',
]);

function toDisplayLabel(phrase: string) {
  const label = phrase.replace(/[a-z]+/g, (word) =>
    PROPER_NAMES.has(word) ? word.charAt(0).toUpperCase() + word.slice(1) : word
  );
  return label.charAt(0).toUpperCase() + label.slice(1);
}

export function NaturalDateInput({
  label,
  value,
  onChange,
  placeholder = 'e.g. tomorrow at 3pm',
}: NaturalDateInputProps) {
  const now = new Date();
  const formattedValue = value ? formatDueDate(value, now) : '';

  const [text, setText] = useState(formattedValue);
  const [error, setError] = useState<string | null>(null);
  const [previousValue, setPreviousValue] = useState(value);
  const selectOnMouseUp = useRef(false);

  // Show the new value when it changes from outside
  if (!sameDate(previousValue, value)) {
    setPreviousValue(value);
    setText(formattedValue);
    setError(null);
  }

  const combobox = useCombobox({
    onDropdownClose: () => combobox.resetSelectedOption(),
  });

  // The formatted value in the input is not a query: show presets for it
  const query = text === formattedValue ? '' : text;
  const suggestions = getSuggestions(query, now);

  const commit = (date: Date | null) => {
    onChange(date);
    setText(date ? formatDueDate(date, now) : '');
    setError(null);
    combobox.closeDropdown();
  };

  const handleOptionSubmit = (optionValue: string) => {
    const suggestion = suggestions[Number(optionValue)];
    if (suggestion) {
      commit(suggestion.date);
    }
  };

  const handleEnter = () => {
    if (text.trim() === '') {
      commit(null);
      return;
    }
    if (text === formattedValue) {
      combobox.closeDropdown();
      return;
    }
    const parsed = parseNaturalDate(text, now);
    if (parsed) {
      commit(parsed.date);
    }
  };

  const handleBlur = () => {
    combobox.closeDropdown();
    if (text.trim() === '') {
      if (value) {
        onChange(null);
      }
      setText('');
      setError(null);
      return;
    }
    if (text === formattedValue) {
      return;
    }
    const parsed = parseNaturalDate(text, now);
    if (parsed) {
      commit(parsed.date);
    } else {
      setError(`Could not understand “${text.trim()}”`);
    }
  };

  const isPast = value !== null && value.getTime() < now.getTime();

  const options = suggestions.map((suggestion, index) => (
    <Combobox.Option value={String(index)} key={suggestion.label} className={classes.option}>
      <Text size="sm">{toDisplayLabel(suggestion.label)}</Text>
      <Text size="xs">
        {formatDueDate(suggestion.date, now)} · {formatRelative(suggestion.date, now)}
      </Text>
    </Combobox.Option>
  ));

  const clearButton =
    text !== '' || value ? (
      <CloseButton
        size="sm"
        aria-label="Clear date"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => commit(null)}
      />
    ) : null;

  return (
    <Combobox store={combobox} onOptionSubmit={handleOptionSubmit}>
      <Combobox.Target>
        <TextInput
          label={label}
          placeholder={placeholder}
          value={text}
          error={error}
          description={
            isPast && !error ? (
              <Group gap={4} component="span" className={classes.warning}>
                <IconAlertTriangle size={14} />
                This date is in the past
              </Group>
            ) : undefined
          }
          inputWrapperOrder={['label', 'input', 'description', 'error']}
          leftSection={<IconCalendar size={16} />}
          rightSection={clearButton}
          onChange={(event) => {
            setText(event.currentTarget.value);
            setError(null);
            combobox.resetSelectedOption();
            combobox.openDropdown();
          }}
          onFocus={(event) => {
            if (value) {
              event.currentTarget.select();
              selectOnMouseUp.current = true;
            }
            combobox.openDropdown();
          }}
          onMouseUp={(event) => {
            // Keep the text selected when focus came from a click
            if (selectOnMouseUp.current) {
              event.preventDefault();
              selectOnMouseUp.current = false;
            }
          }}
          onClick={() => combobox.openDropdown()}
          onBlur={() => {
            selectOnMouseUp.current = false;
            handleBlur();
          }}
          onKeyDown={(event) => {
            selectOnMouseUp.current = false;
            if (event.key === 'Enter' && combobox.getSelectedOptionIndex() === -1) {
              event.preventDefault();
              handleEnter();
            }
          }}
        />
      </Combobox.Target>

      <Combobox.Dropdown>
        <Combobox.Options>
          {options.length > 0 ? (
            options
          ) : (
            <Combobox.Empty>Could not understand “{text.trim()}”</Combobox.Empty>
          )}
        </Combobox.Options>
      </Combobox.Dropdown>
    </Combobox>
  );
}

.option {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.warning {
  margin-top: calc(var(--mantine-spacing-xs) / 2);
  color: var(--mantine-color-orange-text);
}

import { useState } from 'react';
import { render, screen, userEvent, within } from '@test-utils';
import { NaturalDateInput } from './NaturalDateInput';

// Wednesday, October 28, 2026, noon (local time)
const NOW = new Date(2026, 9, 28, 12, 0);

function DueDateField({ initialValue = null }: { initialValue?: Date | null }) {
  const [value, setValue] = useState<Date | null>(initialValue);
  return (
    <>
      <NaturalDateInput label="Due date" value={value} onChange={setValue} />
      <p>Value: {value ? value.toISOString() : 'null'}</p>
    </>
  );
}

function setup(initialValue?: Date | null) {
  const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
  render(<DueDateField initialValue={initialValue} />);
  return { user, input: screen.getByRole('combobox', { name: 'Due date' }) };
}

function expectValue(date: Date | null) {
  expect(screen.getByText(`Value: ${date ? date.toISOString() : 'null'}`)).toBeInTheDocument();
}

function optionLabels() {
  return screen.getAllByRole('option').map((option) => option.firstChild?.textContent);
}

beforeEach(() => {
  jest.useFakeTimers({ now: NOW, advanceTimers: true });
});

afterEach(() => {
  jest.useRealTimers();
});

describe('suggestions', () => {
  it('shows presets when the empty input is focused', async () => {
    const { user, input } = setup();
    await user.click(input);
    expect(optionLabels()).toEqual(['Today', 'Tomorrow', 'Next week', 'End of month']);
  });

  it('completes the typed text', async () => {
    const { user, input } = setup();
    await user.type(input, 'ne');
    expect(optionLabels().slice(0, 3)).toEqual(['Next week', 'Next month', 'Next Monday']);
  });

  it('suggests pm and am times for a weekday and an hour', async () => {
    const { user, input } = setup();
    await user.type(input, 'fri 5');
    expect(optionLabels().slice(0, 2)).toEqual(['Friday at 5pm', 'Friday at 5am']);
  });

  it('shows the resolved date and how far away it is in every suggestion', async () => {
    const { user, input } = setup();
    await user.type(input, 'fri 5');
    const option = screen.getByRole('option', { name: /^Friday at 5pm/ });
    expect(within(option).getByText('Fri, Oct 30, 5:00 PM · in 2 days')).toBeInTheDocument();
  });

  it('keeps the presets casing in filtered suggestions', async () => {
    const { user, input } = setup();
    await user.type(input, 'tom');
    expect(optionLabels()[0]).toBe('Tomorrow');
  });

  it('shows at most five suggestions', async () => {
    const { user, input } = setup();
    await user.type(input, '3');
    expect(screen.getAllByRole('option')).toHaveLength(5);
  });

  it('shows a message instead of suggestions for text that is not understood', async () => {
    const { user, input } = setup();
    await user.type(input, 'qwerty');
    expect(screen.getByText('Could not understand “qwerty”')).toBeInTheDocument();
    expect(screen.queryByRole('option')).not.toBeInTheDocument();
  });
});

describe('picking a date', () => {
  it('sets the value when a suggestion is clicked', async () => {
    const { user, input } = setup();
    await user.type(input, 'fri 5');
    await user.click(screen.getByRole('option', { name: /^Friday at 5pm/ }));
    expectValue(new Date(2026, 9, 30, 17, 0));
  });

  it('shows the formatted date in the input after a pick', async () => {
    const { user, input } = setup();
    await user.type(input, 'fri 5');
    await user.click(screen.getByRole('option', { name: /^Friday at 5pm/ }));
    expect(input).toHaveValue('Fri, Oct 30, 5:00 PM');
  });

  it('sets a preset picked with the keyboard', async () => {
    const { user, input } = setup();
    await user.click(input);
    await user.keyboard('{ArrowDown}{ArrowDown}{Enter}');
    expectValue(new Date(2026, 9, 29, 23, 59, 59, 999));
  });

  it('sets the value when Enter is pressed on text that is understood', async () => {
    const { user, input } = setup();
    await user.type(input, 'next friday at 3pm{Enter}');
    expectValue(new Date(2026, 10, 6, 15, 0));
  });

  it('shows a date without a time without the time', async () => {
    const { user, input } = setup();
    await user.type(input, 'mar 5{Enter}');
    expect(input).toHaveValue('Fri, Mar 5, 2027');
  });

  it('keeps the value when Enter is pressed on text that is not understood', async () => {
    const { user, input } = setup();
    await user.type(input, 'qwerty{Enter}');
    expectValue(null);
  });

  it('selects the text of an input with a value on focus', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(input);
    const element = input as HTMLInputElement;
    expect([element.selectionStart, element.selectionEnd]).toEqual([0, element.value.length]);
  });

  it('replaces the value when the user types over it', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(input);
    await user.keyboard('tomorrow{Enter}');
    expectValue(new Date(2026, 9, 29, 23, 59, 59, 999));
  });

  it('shows presets when an input with a value is focused', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(input);
    expect(optionLabels()).toEqual(['Today', 'Tomorrow', 'Next week', 'End of month']);
  });
});

describe('blur', () => {
  it('shows an error for text that is not understood', async () => {
    const { user, input } = setup();
    await user.type(input, 'qwerty');
    await user.tab();
    expect(input).toHaveAccessibleDescription('Could not understand “qwerty”');
  });

  it('keeps the previous value when the text is not understood', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(input);
    await user.keyboard('qwerty');
    await user.tab();
    expectValue(new Date(2026, 9, 30, 17, 0));
  });

  it('clears the value when the text is empty', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.clear(input);
    await user.tab();
    expectValue(null);
  });

  it('sets the value when the text is understood', async () => {
    const { user, input } = setup();
    await user.type(input, 'in 2 weeks');
    await user.tab();
    expectValue(new Date(2026, 10, 11, 23, 59, 59, 999));
  });

  it('keeps the value when the formatted text is left unchanged', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(input);
    await user.tab();
    expect(input).toHaveValue('Fri, Oct 30, 5:00 PM');
  });
});

describe('value', () => {
  it('shows the value from props formatted in the input', () => {
    const { input } = setup(new Date(2027, 2, 5, 9, 30));
    expect(input).toHaveValue('Fri, Mar 5, 2027, 9:30 AM');
  });

  it('warns about a date in the past', async () => {
    const { user, input } = setup();
    await user.type(input, 'yesterday{Enter}');
    expect(screen.getByText('This date is in the past')).toBeInTheDocument();
  });

  it('does not warn about a date later today', async () => {
    const { user, input } = setup();
    await user.type(input, 'today{Enter}');
    expect(screen.queryByText('This date is in the past')).not.toBeInTheDocument();
  });

  it('clears the value with the clear button', async () => {
    const { user, input } = setup(new Date(2026, 9, 30, 17, 0));
    await user.click(screen.getByRole('button', { name: 'Clear date' }));
    expectValue(null);
    expect(input).toHaveValue('');
  });
});

import { useState } from 'react';
import { Stack, Text } from '@mantine/core';
import { NaturalDateInput } from './NaturalDateInput';

export function NaturalDateInputDemo() {
  const [value, setValue] = useState<Date | null>(null);

  return (
    <Stack gap="xs">
      <NaturalDateInput label="Due date" value={value} onChange={setValue} />
      <Text size="sm">Value: {value ? value.toISOString() : 'null'}</Text>
    </Stack>
  );
}

import {
  formatDueDate,
  formatRelative,
  parseNaturalDate,
  type ParsedDate,
} from './parseNaturalDate';

// Wednesday, October 28, 2026, noon (local time)
const NOW = new Date(2026, 9, 28, 12, 0);

function endOfDay(year: number, month: number, day: number) {
  return new Date(year, month, day, 23, 59, 59, 999);
}

function parse(text: string, now = NOW): ParsedDate | null {
  return parseNaturalDate(text, now);
}

describe('parseNaturalDate', () => {
  describe('relative days', () => {
    it.each([
      ['today', endOfDay(2026, 9, 28)],
      ['tomorrow', endOfDay(2026, 9, 29)],
      ['yesterday', endOfDay(2026, 9, 27)],
    ])('resolves "%s"', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('ignores case and extra spaces', () => {
      expect(parse('  ToMoRRow ')?.date).toEqual(endOfDay(2026, 9, 29));
    });

    it('marks a date without a time as due at the end of the day', () => {
      expect(parse('tomorrow')?.hasTime).toBe(false);
    });
  });

  describe('weekdays', () => {
    it.each([
      ['fri', endOfDay(2026, 9, 30)],
      ['friday', endOfDay(2026, 9, 30)],
      ['mon', endOfDay(2026, 10, 2)],
      ['thurs', endOfDay(2026, 9, 29)],
    ])('resolves "%s" to the next such day', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('resolves the current weekday to the same day of the next week', () => {
      expect(parse('wednesday')?.date).toEqual(endOfDay(2026, 10, 4));
    });

    it.each([
      ['next friday', endOfDay(2026, 10, 6)],
      ['next mon', endOfDay(2026, 10, 2)],
      ['next sunday', endOfDay(2026, 10, 8)],
    ])('resolves "%s" to that day of the next week', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('resolves "this monday" to the Monday of the current week', () => {
      expect(parse('this monday')?.date).toEqual(endOfDay(2026, 9, 26));
    });
  });

  describe('offsets', () => {
    it.each([
      ['in 3 days', endOfDay(2026, 9, 31)],
      ['in 1 day', endOfDay(2026, 9, 29)],
      ['in 2 weeks', endOfDay(2026, 10, 11)],
      ['in a week', endOfDay(2026, 10, 4)],
      ['in 1 month', endOfDay(2026, 10, 28)],
      ['in 3 months', endOfDay(2027, 0, 28)],
      ['5 days from now', endOfDay(2026, 10, 2)],
      ['2 weeks from now', endOfDay(2026, 10, 11)],
    ])('resolves "%s"', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('clamps a month offset to the last day of a shorter month', () => {
      expect(parse('in 1 month', new Date(2027, 0, 31, 9))?.date).toEqual(endOfDay(2027, 1, 28));
    });
  });

  describe('weeks and months', () => {
    it.each([
      ['next week', endOfDay(2026, 10, 2)],
      ['next month', endOfDay(2026, 10, 1)],
      ['end of week', endOfDay(2026, 10, 1)],
      ['end of month', endOfDay(2026, 9, 31)],
    ])('resolves "%s"', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('starts weeks on Monday when today is Sunday', () => {
      const sunday = new Date(2026, 10, 1, 10);
      expect(parse('next week', sunday)?.date).toEqual(endOfDay(2026, 10, 2));
    });

    it('resolves "end of week" on Sunday to that Sunday', () => {
      const sunday = new Date(2026, 10, 1, 10);
      expect(parse('end of week', sunday)?.date).toEqual(endOfDay(2026, 10, 1));
    });
  });

  describe('calendar dates', () => {
    it.each([
      ['mar 5', endOfDay(2027, 2, 5)],
      ['March 5', endOfDay(2027, 2, 5)],
      ['5 march', endOfDay(2027, 2, 5)],
      ['5th of march', endOfDay(2027, 2, 5)],
      ['march 5 2027', endOfDay(2027, 2, 5)],
      ['march 5, 2028', endOfDay(2028, 2, 5)],
      ['2027-03-05', endOfDay(2027, 2, 5)],
      ['3/5', endOfDay(2027, 2, 5)],
      ['3/5/2027', endOfDay(2027, 2, 5)],
      ['dec 25', endOfDay(2026, 11, 25)],
      ['12/25', endOfDay(2026, 11, 25)],
    ])('resolves "%s"', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('resolves a date without a year that already passed to next year', () => {
      expect(parse('oct 27')?.date).toEqual(endOfDay(2027, 9, 27));
    });

    it('resolves a date without a year that is today to today', () => {
      expect(parse('oct 28')?.date).toEqual(endOfDay(2026, 9, 28));
    });

    it('accepts a past date with an explicit year', () => {
      expect(parse('2025-01-15')?.date).toEqual(endOfDay(2025, 0, 15));
    });

    it.each(['feb 30', '2026-02-29', '13/1', '0/5', 'mar 32'])(
      'rejects the invalid date "%s"',
      (text) => {
        expect(parse(text)).toBeNull();
      }
    );

    it('resolves Feb 29 without a year to the next leap year', () => {
      expect(parse('feb 29')?.date).toEqual(endOfDay(2028, 1, 29));
    });

    it('reads its own formatted output back', () => {
      const date = new Date(2027, 2, 5, 15, 30);
      expect(parse(formatDueDate(date, NOW))?.date).toEqual(date);
    });
  });

  describe('times', () => {
    it.each([
      ['at 3pm', new Date(2026, 9, 28, 15, 0)],
      ['3:30pm', new Date(2026, 9, 28, 15, 30)],
      ['3:30 PM', new Date(2026, 9, 28, 15, 30)],
      ['15:30', new Date(2026, 9, 28, 15, 30)],
      ['noon', new Date(2026, 9, 28, 12, 0)],
      ['midnight', new Date(2026, 9, 28, 0, 0)],
      ['12am', new Date(2026, 9, 28, 0, 0)],
      ['12pm', new Date(2026, 9, 28, 12, 0)],
    ])('resolves "%s" to today at that time', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it.each([
      ['tomorrow at 3pm', new Date(2026, 9, 29, 15, 0)],
      ['friday at 5pm', new Date(2026, 9, 30, 17, 0)],
      ['next friday 9am', new Date(2026, 10, 6, 9, 0)],
      ['mar 5 at noon', new Date(2027, 2, 5, 12, 0)],
      ['2027-03-05 15:30', new Date(2027, 2, 5, 15, 30)],
      ['in 2 days at midnight', new Date(2026, 9, 30, 0, 0)],
      ['end of month at 5:45pm', new Date(2026, 9, 31, 17, 45)],
      ['3pm today', new Date(2026, 9, 28, 15, 0)],
      ['9am tomorrow', new Date(2026, 9, 29, 9, 0)],
    ])('resolves "%s"', (text, expected) => {
      expect(parse(text)?.date).toEqual(expected);
    });

    it('marks a date with a time', () => {
      expect(parse('tomorrow at 3pm')?.hasTime).toBe(true);
    });

    it.each(['13pm', '25:00', '3:75pm', 'tomorrow at 3'])(
      'rejects the invalid time "%s"',
      (text) => {
        expect(parse(text)).toBeNull();
      }
    );
  });

  it.each(['', 'blah', 'fri 5', 'next', 'in days', 'march'])('returns null for "%s"', (text) => {
    expect(parse(text)).toBeNull();
  });
});

describe('formatDueDate', () => {
  it('shows weekday, month, day and time', () => {
    expect(formatDueDate(new Date(2026, 9, 30, 15, 0), NOW)).toBe('Fri, Oct 30, 3:00 PM');
  });

  it('leaves the time out at the end of the day', () => {
    expect(formatDueDate(endOfDay(2026, 9, 30), NOW)).toBe('Fri, Oct 30');
  });

  it('shows the year when it is not the current one', () => {
    expect(formatDueDate(endOfDay(2027, 2, 5), NOW)).toBe('Fri, Mar 5, 2027');
  });

  it('shows midnight as 12:00 AM', () => {
    expect(formatDueDate(new Date(2026, 9, 30, 0, 5), NOW)).toBe('Fri, Oct 30, 12:05 AM');
  });
});

describe('formatRelative', () => {
  it.each([
    [endOfDay(2026, 9, 28), 'today'],
    [endOfDay(2026, 9, 29), 'tomorrow'],
    [endOfDay(2026, 9, 27), 'yesterday'],
    [new Date(2026, 9, 30, 15), 'in 2 days'],
    [endOfDay(2026, 9, 25), '3 days ago'],
    [endOfDay(2026, 10, 18), 'in 3 weeks'],
    [endOfDay(2027, 2, 5), 'in 4 months'],
    [endOfDay(2028, 9, 28), 'in 2 years'],
    [new Date(2026, 9, 28, 15), 'in 3 hours'],
    [new Date(2026, 9, 28, 12, 20), 'in 20 minutes'],
    [new Date(2026, 9, 28, 9), '3 hours ago'],
    [new Date(2026, 9, 28, 13), 'in 1 hour'],
  ])('describes %s as "%s"', (date, expected) => {
    expect(formatRelative(date, NOW)).toBe(expected);
  });
});

export interface ParsedDate {
  /** Resolved moment; a date without a time is due at the end of that day */
  date: Date;
  hasTime: boolean;
}

const DAY_MS = 24 * 60 * 60 * 1000;

export const WEEKDAYS = [
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
  'sunday',
] as const;

const WEEKDAY_ALIASES: Record<string, number> = {
  mon: 0,
  tue: 1,
  tues: 1,
  wed: 2,
  thu: 3,
  thur: 3,
  thurs: 3,
  fri: 4,
  sat: 5,
  sun: 6,
};

export const MONTHS = [
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
] as const;

const NUMBER_WORDS: Record<string, number> = { a: 1, an: 1, one: 1, two: 2, three: 3 };

/** Lowercases, drops commas and joins "3 pm" into "3pm" */
export function normalizePhrase(input: string) {
  return input
    .toLowerCase()
    .replace(/[,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/(\d)\s+(am|pm|a\.m\.|p\.m\.)(?=\s|$)/g, '$1$2');
}

export function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, days: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function addMonths(date: Date, months: number) {
  const target = new Date(date.getFullYear(), date.getMonth() + months, 1);
  const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate();
  return new Date(target.getFullYear(), target.getMonth(), Math.min(date.getDate(), lastDay));
}

/** 0 = Monday … 6 = Sunday */
function weekdayIndex(date: Date) {
  return (date.getDay() + 6) % 7;
}

function startOfWeek(date: Date) {
  return addDays(date, -weekdayIndex(date));
}

function parseWeekday(token: string): number | null {
  const full = WEEKDAYS.indexOf(token as (typeof WEEKDAYS)[number]);
  if (full !== -1) {
    return full;
  }
  return token in WEEKDAY_ALIASES ? WEEKDAY_ALIASES[token] : null;
}

function parseMonth(token: string): number | null {
  if (token.length < 3) {
    return null;
  }
  if (token === 'sept') {
    return 8;
  }
  const index = MONTHS.findIndex((month) => month.startsWith(token));
  return index === -1 ? null : index;
}

function parseCount(token: string): number | null {
  if (/^\d{1,4}$/.test(token)) {
    return Number(token);
  }
  return token in NUMBER_WORDS ? NUMBER_WORDS[token] : null;
}

function addUnit(date: Date, count: number, unit: string) {
  if (unit.startsWith('day')) {
    return addDays(date, count);
  }
  if (unit.startsWith('week')) {
    return addDays(date, count * 7);
  }
  if (unit.startsWith('month')) {
    return addMonths(date, count);
  }
  return addMonths(date, count * 12);
}

/** Builds a valid calendar date or null for overflowing days (Feb 30) */
function calendarDate(year: number, month: number, day: number) {
  const date = new Date(year, month, day);
  if (date.getMonth() !== month || date.getDate() !== day) {
    return null;
  }
  if (year < 100) {
    date.setFullYear(year);
  }
  return date;
}

/** A date without a year is the next such date, today included */
function nextCalendarDate(month: number, day: number, today: Date) {
  // Feb 29 may only exist in one of the next few years
  for (let year = today.getFullYear(); year <= today.getFullYear() + 8; year += 1) {
    const date = calendarDate(year, month, day);
    if (date && date >= today) {
      return date;
    }
  }
  return null;
}

function explicitDate(month: number, day: number, year: string | undefined, today: Date) {
  if (year === undefined) {
    return nextCalendarDate(month, day, today);
  }
  const fullYear = year.length === 2 ? 2000 + Number(year) : Number(year);
  return calendarDate(fullYear, month, day);
}

const UNIT = '(days?|weeks?|months?|years?)';
const ORDINAL = '(\\d{1,2})(?:st|nd|rd|th)?';

/** Parses the date part of a phrase into the start of that day */
export function parseDatePart(phrase: string, now: Date): Date | null {
  const today = startOfDay(now);
  let match: RegExpMatchArray | null;

  if (phrase === 'today') {
    return today;
  }
  if (phrase === 'tomorrow') {
    return addDays(today, 1);
  }
  if (phrase === 'yesterday') {
    return addDays(today, -1);
  }
  if (phrase === 'next week') {
    return addDays(startOfWeek(today), 7);
  }
  if (phrase === 'next month') {
    return new Date(today.getFullYear(), today.getMonth() + 1, 1);
  }
  if (/^end of (the )?week$/.test(phrase)) {
    return addDays(startOfWeek(today), 6);
  }
  if (/^end of (the )?month$/.test(phrase)) {
    return new Date(today.getFullYear(), today.getMonth() + 1, 0);
  }

  if ((match = phrase.match(/^(?:(next|this) )?([a-z]+)$/))) {
    const weekday = parseWeekday(match[2]);
    if (weekday !== null) {
      if (match[1] === 'next') {
        return addDays(startOfWeek(today), 7 + weekday);
      }
      if (match[1] === 'this') {
        return addDays(startOfWeek(today), weekday);
      }
      return addDays(today, (weekday - weekdayIndex(today) + 7) % 7 || 7);
    }
  }

  if ((match = phrase.match(new RegExp(`^in ([a-z]+|\\d{1,4}) ${UNIT}$`)))) {
    const count = parseCount(match[1]);
    return count === null ? null : addUnit(today, count, match[2]);
  }
  if ((match = phrase.match(new RegExp(`^([a-z]+|\\d{1,4}) ${UNIT} from (now|today)$`)))) {
    const count = parseCount(match[1]);
    return count === null ? null : addUnit(today, count, match[2]);
  }

  if ((match = phrase.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) {
    return calendarDate(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  }
  if ((match = phrase.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{4}|\d{2}))?$/))) {
    return explicitDate(Number(match[1]) - 1, Number(match[2]), match[3], today);
  }

  // A weekday in front of an explicit date is accepted and ignored ("fri oct 30")
  const withoutWeekday = phrase.replace(/^([a-z]+) (?=\S+ \S+)/, (whole, word: string) =>
    parseWeekday(word) === null ? whole : ''
  );

  if ((match = withoutWeekday.match(new RegExp(`^([a-z]+)\\.? ${ORDINAL}(?: (\\d{4}))?$`)))) {
    const month = parseMonth(match[1]);
    return month === null ? null : explicitDate(month, Number(match[2]), match[3], today);
  }
  if (
    (match = withoutWeekday.match(new RegExp(`^${ORDINAL} (?:of )?([a-z]+)\\.?(?: (\\d{4}))?$`)))
  ) {
    const month = parseMonth(match[2]);
    return month === null ? null : explicitDate(month, Number(match[1]), match[3], today);
  }

  return null;
}

interface Time {
  hours: number;
  minutes: number;
}

/** Parses "3pm", "3:30pm", "15:30", "noon", "midnight", optionally after "at" */
export function parseTime(input: string): Time | null {
  const phrase = input.replace(/^at /, '');
  let match: RegExpMatchArray | null;

  if (phrase === 'noon') {
    return { hours: 12, minutes: 0 };
  }
  if (phrase === 'midnight') {
    return { hours: 0, minutes: 0 };
  }
  if ((match = phrase.match(/^(\d{1,2})(?::(\d{2}))?(am|pm|a\.m\.|p\.m\.)$/))) {
    const hours = Number(match[1]);
    const minutes = Number(match[2] ?? 0);
    if (hours < 1 || hours > 12 || minutes > 59) {
      return null;
    }
    const pm = match[3].startsWith('p');
    return { hours: (hours % 12) + (pm ? 12 : 0), minutes };
  }
  if ((match = phrase.match(/^(\d{1,2}):(\d{2})$/))) {
    const hours = Number(match[1]);
    const minutes = Number(match[2]);
    return hours > 23 || minutes > 59 ? null : { hours, minutes };
  }
  return null;
}

function withTime(day: Date, time: Time | null): ParsedDate {
  const date = new Date(day);
  if (time) {
    date.setHours(time.hours, time.minutes, 0, 0);
  } else {
    date.setHours(23, 59, 59, 999);
  }
  return { date, hasTime: time !== null };
}

function dropTrailingAt(tokens: string[]) {
  return tokens[tokens.length - 1] === 'at' ? tokens.slice(0, -1) : tokens;
}

/**
 * Parses a plain English due date ("next friday at 3pm", "mar 5", "in 2 weeks")
 * relative to `now`. Returns null when the text is not understood.
 */
export function parseNaturalDate(input: string, now: Date = new Date()): ParsedDate | null {
  const phrase = normalizePhrase(input);
  if (phrase === '') {
    return null;
  }

  const plainDate = parseDatePart(phrase, now);
  if (plainDate) {
    return withTime(plainDate, null);
  }

  const tokens = phrase.split(' ');

  // Time after the date: "friday at 3pm", "mar 5 15:30"
  for (let count = 1; count <= Math.min(2, tokens.length); count += 1) {
    const time = parseTime(tokens.slice(-count).join(' '));
    if (time) {
      const rest = dropTrailingAt(tokens.slice(0, -count)).join(' ');
      const day = rest === '' ? startOfDay(now) : parseDatePart(rest, now);
      if (day) {
        return withTime(day, time);
      }
    }
  }

  // Time before the date: "3pm today", "at noon tomorrow"
  for (let count = 1; count < Math.min(3, tokens.length); count += 1) {
    const time = parseTime(tokens.slice(0, count).join(' '));
    if (time) {
      const day = parseDatePart(tokens.slice(count).join(' '), now);
      if (day) {
        return withTime(day, time);
      }
    }
  }

  return null;
}

export function isEndOfDay(date: Date) {
  return (
    date.getHours() === 23 &&
    date.getMinutes() === 59 &&
    date.getSeconds() === 59 &&
    date.getMilliseconds() === 999
  );
}

const SHORT_WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const SHORT_MONTHS = MONTHS.map((month) => month.charAt(0).toUpperCase() + month.slice(1, 3));

/** "Fri, Oct 30, 3:00 PM"; the year only when it is not the current one, the time only when set */
export function formatDueDate(date: Date, now: Date = new Date()) {
  let result = `${SHORT_WEEKDAYS[date.getDay()]}, ${SHORT_MONTHS[date.getMonth()]} ${date.getDate()}`;
  if (date.getFullYear() !== now.getFullYear()) {
    result += `, ${date.getFullYear()}`;
  }
  if (!isEndOfDay(date)) {
    const hours = date.getHours() % 12 || 12;
    const minutes = String(date.getMinutes()).padStart(2, '0');
    result += `, ${hours}:${minutes} ${date.getHours() < 12 ? 'AM' : 'PM'}`;
  }
  return result;
}

function plural(count: number, unit: string) {
  return `${count} ${unit}${count === 1 ? '' : 's'}`;
}

function relative(count: number, unit: string) {
  return count > 0 ? `in ${plural(count, unit)}` : `${plural(-count, unit)} ago`;
}

/** How far the date is from now: "today", "in 4 days", "2 hours ago" */
export function formatRelative(date: Date, now: Date = new Date()) {
  const days = Math.round((startOfDay(date).getTime() - startOfDay(now).getTime()) / DAY_MS);

  if (days === 0 && !isEndOfDay(date)) {
    const minutes = Math.round((date.getTime() - now.getTime()) / 60000);
    if (minutes === 0) {
      return 'now';
    }
    if (Math.abs(minutes) < 60) {
      return relative(minutes, 'minute');
    }
    return relative(Math.trunc(minutes / 60), 'hour');
  }

  if (days === 0) {
    return 'today';
  }
  if (days === 1) {
    return 'tomorrow';
  }
  if (days === -1) {
    return 'yesterday';
  }
  if (Math.abs(days) < 14) {
    return relative(days, 'day');
  }
  if (Math.abs(days) < 60) {
    return relative(Math.round(days / 7), 'week');
  }
  if (Math.abs(days) < 365) {
    return relative(Math.round(days / 30), 'month');
  }
  return relative(Math.round(days / 365), 'year');
}

import { getPresets, getSuggestions } from './suggestions';

// Wednesday, October 28, 2026, noon (local time)
const NOW = new Date(2026, 9, 28, 12, 0);

function labels(query: string) {
  return getSuggestions(query, NOW).map((suggestion) => suggestion.label);
}

describe('getSuggestions', () => {
  it('shows presets for an empty query', () => {
    expect(labels('')).toEqual(['Today', 'Tomorrow', 'Next week', 'End of month']);
  });

  it('resolves presets to their dates', () => {
    expect(getPresets(NOW).map((preset) => preset.date)).toEqual([
      new Date(2026, 9, 28, 23, 59, 59, 999),
      new Date(2026, 9, 29, 23, 59, 59, 999),
      new Date(2026, 10, 2, 23, 59, 59, 999),
      new Date(2026, 9, 31, 23, 59, 59, 999),
    ]);
  });

  it('completes "ne" with next week, next month and next weekdays', () => {
    expect(labels('ne').slice(0, 3)).toEqual(['next week', 'next month', 'next monday']);
  });

  it('completes a number with offsets and times', () => {
    expect(labels('3').slice(0, 3)).toEqual(['in 3 days', 'in 3 weeks', '3pm today']);
  });

  it('completes a weekday and an hour with pm and am times', () => {
    expect(labels('fri 5').slice(0, 2)).toEqual(['friday at 5pm', 'friday at 5am']);
  });

  it('completes an hour with minutes', () => {
    expect(labels('tomorrow 5:3').slice(0, 2)).toEqual([
      'tomorrow at 5:30pm',
      'tomorrow at 5:30am',
    ]);
  });

  it('suggests a 24-hour time for hours after noon', () => {
    expect(labels('tomorrow at 17')).toContain('tomorrow at 17:00');
  });

  it('completes a partial phrase', () => {
    expect(labels('end of m')[0]).toBe('end of month');
  });

  it('puts the typed text first when it is understood', () => {
    expect(labels('mar 5')[0]).toBe('mar 5');
  });

  it('leaves out longer spellings of the typed date', () => {
    expect(labels('mar 5')).not.toContain('march 5');
  });

  it('returns at most five suggestions', () => {
    expect(labels('n')).toHaveLength(5);
  });

  it('resolves every suggestion to its date', () => {
    const [first] = getSuggestions('fri 5', NOW);
    expect(first.date).toEqual(new Date(2026, 9, 30, 17, 0));
  });

  it('returns nothing for text that is not a date', () => {
    expect(labels('qwerty')).toEqual([]);
  });
});

import { MONTHS, normalizePhrase, parseNaturalDate, WEEKDAYS } from './parseNaturalDate';

export interface DateSuggestion {
  /** Text shown in the option */
  label: string;
  date: Date;
}

export const MAX_SUGGESTIONS = 5;

const PRESETS = ['Today', 'Tomorrow', 'Next week', 'End of month'];

const DATE_PHRASES = [
  'today',
  'tomorrow',
  'yesterday',
  'next week',
  'next month',
  'end of week',
  'end of month',
  ...WEEKDAYS,
  ...WEEKDAYS.map((weekday) => `next ${weekday}`),
];

const DEFAULT_TIMES = ['at 9am', 'at noon', 'at 5pm'];

/** Presets shown when the input is empty */
export function getPresets(now: Date = new Date()): DateSuggestion[] {
  return PRESETS.map((label) => ({ label, date: parseNaturalDate(label, now)!.date }));
}

/** Times the typed number may stand for: "5" → "5pm", "5am"; "17" → "17:00" */
function timeVariants(hours: number, minutes: string | undefined) {
  const suffix = minutes === undefined ? '' : `:${minutes}`;
  if (hours >= 1 && hours <= 12) {
    return [`${hours}${suffix}pm`, `${hours}${suffix}am`];
  }
  if (hours >= 13 && hours <= 23) {
    return [`${hours}:${minutes ?? '00'}`];
  }
  return [];
}

/** Phrases that may complete the query, in the order they are suggested */
function candidatePhrases(query: string) {
  const numberMatch = query.match(/(?:^|\s)(\d{1,3})(?::(\d{0,2}))?(?:[ap]m?)?(?=\s|$)/);
  if (!numberMatch) {
    return [
      ...DATE_PHRASES,
      ...DATE_PHRASES.flatMap((phrase) => DEFAULT_TIMES.map((time) => `${phrase} ${time}`)),
    ];
  }

  const count = Number(numberMatch[1]);
  const minutes = numberMatch[2] === undefined ? undefined : numberMatch[2].padEnd(2, '0');
  const times = timeVariants(count, minutes);
  const phrases: string[] = [];

  if (minutes === undefined && count > 0) {
    phrases.push(`in ${count} days`, `in ${count} weeks`);
    if (times.length > 0) {
      phrases.push(`${times[0]} today`);
    }
    phrases.push(`in ${count} months`);
    if (times.length > 1) {
      phrases.push(`${times[1]} tomorrow`);
    }
    phrases.push(`${count} days from now`, `${count} weeks from now`);
  } else {
    phrases.push(...times.map((time) => `${time} today`));
  }

  phrases.push(...DATE_PHRASES.flatMap((phrase) => times.map((time) => `${phrase} at ${time}`)));

  if (minutes === undefined && count >= 1 && count <= 31) {
    phrases.push(...MONTHS.map((month) => `${month} ${count}`));
  }

  return phrases;
}

/** Every query word is the start of a phrase word, in the same order: "fri 5" ~ "friday at 5pm" */
function matchesWords(queryWords: string[], phrase: string) {
  const phraseWords = phrase.split(' ');
  let position = 0;
  return queryWords.every((word) => {
    while (position < phraseWords.length && !phraseWords[position].startsWith(word)) {
      position += 1;
    }
    position += 1;
    return position <= phraseWords.length;
  });
}

/**
 * Up to five phrases that complete the query and resolve to a date.
 * When the query itself is understood it comes first.
 */
export function getSuggestions(query: string, now: Date = new Date()): DateSuggestion[] {
  const normalized = normalizePhrase(query);
  if (normalized === '') {
    return getPresets(now);
  }

  const suggestions: DateSuggestion[] = [];
  const typed = parseNaturalDate(query, now);
  if (typed) {
    suggestions.push({ label: query.trim().replace(/\s+/g, ' '), date: typed.date });
  }

  const queryWords = normalized.split(' ');
  for (const phrase of candidatePhrases(normalized)) {
    if (suggestions.length >= MAX_SUGGESTIONS) {
      break;
    }
    if (!matchesWords(queryWords, phrase) || normalizePhrase(phrase) === normalized) {
      continue;
    }
    const parsed = parseNaturalDate(phrase, now);
    // A longer spelling of what was typed ("march 5" for "mar 5") adds nothing
    if (!parsed || (typed && parsed.date.getTime() === typed.date.getTime())) {
      continue;
    }
    suggestions.push({ label: phrase, date: parsed.date });
  }

  return suggestions;
}
